var B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function unb64(x){
  var out = '', buf = 0, bits = 0;
  x = String(x).replace(/[^A-Za-z0-9+/=]/g, '');
  for (var j = 0; j < x.length; j++) {
    var ch = x.charAt(j);
    if (ch === '=') { break; }
    var v = B64.indexOf(ch);
    if (v < 0) { continue; }
    buf = (buf << 6) | v;
    bits += 6;
    if (bits >= 8) { bits -= 8; out += String.fromCharCode((buf >> bits) & 0xFF); }
  }
  return out;
}
function deobf(x){
  var bin = unb64(x), s = '', need = 0, cp = 0;
  for (var i = 0; i < bin.length; i++) {
    var b = bin.charCodeAt(i) ^ ((i % 127) + 1);
    if (need === 0) {
      if (b < 0x80) { s += String.fromCharCode(b); }
      else if (b >= 0xC0 && b < 0xE0) { cp = b & 0x1F; need = 1; }
      else if (b >= 0xE0 && b < 0xF0) { cp = b & 0x0F; need = 2; }
      else if (b >= 0xF0) { cp = b & 0x07; need = 3; }
      else { s += String.fromCharCode(b); }
    } else {
      cp = (cp << 6) | (b & 0x3F);
      need--;
      if (need === 0) {
        if (cp > 0xFFFF) { cp -= 0x10000; s += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF)); }
        else { s += String.fromCharCode(cp); }
      }
    }
  }
  return s;
}
var parts = [];
var hit = String(result).match(/data-obf="([^"]+)"/g);
if (hit && hit.length) {
  for (var j = 0; j < hit.length; j++) { parts.push(hit[j].slice(10, -1)); }
} else {
  parts = String(result).split(/\s+/);
}
var out = [];
for (var m = 0; m < parts.length; m++) {
  var p = String(parts[m]).replace(/^\s+|\s+$/g, '');
  if (!p) { continue; }
  var d = deobf(p);
  if (d) { out.push(d.replace(/^\s+|\s+$/g, '')); }
}
return out.join('\n');

